function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function safeBool(v) {
  if (v === true) return true;
  if (typeof v === 'string') return v.trim().toLowerCase() === 'true';
  return false;
}
const items = $input.all();
return items.filter(item => {
  const j = item.json || {};
  // FIX 2026-07-26 (Nutzerwunsch): bisher hart auf sharepicNeedStage=topic_ok beschraenkt, mit
  // einem Kommentar, der (faelschlich) Paritaet mit ALLRIS_P8_Partei_Webseite behauptete - P8
  // selbst verlangt nur echten Content (websiteArticle), die Bild-Wartebedingung gilt dort nur
  // zusaetzlich bei topic_ok. Jetzt dasselbe Muster: instagramCaption (echter Content) ist die
  // Grundvoraussetzung, die Bild-Wartebedingung (unten) bleibt nur fuer topic_ok bestehen.
  if (!safeStr(j.instagramCaption)) return false;
  if (safeBool(j.mastodonPosted)) return false;
  if (!safeStr(j.vorgangKey)) return false;
  // FIX 2026-07-25 (Nutzerfund): P9 lief vor P6 (Bildgenerierung) her - Vorgaenge mit
  // sharepicNeedStage=topic_ok wollen IMMER ein Bild, wurden aber schon text-only gepostet,
  // bevor das Bild fertig war (mastodonPosted=true verhindert seither jede Nachbesserung).
  // Exakt dasselbe Wettlauf-Muster wie P7 vs. P4 vom selben Tag, hier P9 vs. P6. Nur bei
  // 'topic_error_final' (Bildkonzept endgueltig gescheitert) wird bewusst text-only gepostet,
  // sonst wird auf das Bild gewartet. Gilt nur fuer topic_ok - andere Vorgaenge (not_applicable/
  // topic_error) wollten ohnehin nie ein Bild und posten sofort text-only.
  if (safeStr(j.sharepicNeedStage) === 'topic_ok') {
    const hasImage = !!safeStr(j.imageFinalPath);
    const imageGivenUp = safeStr(j.imageStage) === 'topic_error_final';
    const waitingForImage = !hasImage && !imageGivenUp;
    if (waitingForImage) return false;
  }
  // FIX 2026-07-25 (Nutzerwunsch): Mastodon-Post verlinkt auf den diePARTEI-Wordpress-Artikel,
  // muss also IMMER nach P8 kommen, nie davor - sonst gibt es noch keinen Link. Wartet auf
  // wordpressGoslarPosted UND den tatsaechlichen Link (P8 kann theoretisch posted=true haben,
  // ohne dass der Link-Fix schon lief - beide pruefen ist der sichere Weg).
  if (!safeBool(j.wordpressGoslarPosted)) return false;
  if (!safeStr(j.wordpressGoslarPostLink)) return false;
  return true;
});

// FIX 2026-07-28: P9 hatte bisher kein 'nur 1 pro Lauf'-Limit (im Unterschied zu P8b) -
// es postete bei jedem Lauf ALLE gerade faelligen Kandidaten. Jetzt auf genau 1 pro Lauf
// begrenzt (aeltestes lastAnalysisAt zuerst), damit die zwei taeglichen Zeitpunkte
// zuverlaessig 2 Posts/Tag ergeben statt einer variablen Anzahl.
return [...items].sort((a, b) => {
  const ta = Date.parse(a.json.lastAnalysisAt || '') || 0;
  const tb = Date.parse(b.json.lastAnalysisAt || '') || 0;
  return ta - tb;
}).slice(0, 1);

const now = Date.now();
const owner = `ALLRIS_P9_Mastodon_Publish:${$execution.id}`;
return items
  .filter(item => {
    const j = item.json || {};
    const oldOwner = String(j.claim_owner || '').trim();
    const expires = Date.parse(String(j.claim_expires_at || ''));
    return !oldOwner || !Number.isFinite(expires) || expires <= now;
  })
  .map(item => ({ json: {
    ...item.json,
    claimAction: 'acquire',
    claimOwner: owner,
    claimStage: 'publication',
    leaseMinutes: 30,
    expectedClaimOwner: item.json.claim_owner ?? null,
    expectedClaimExpiresAt: item.json.claim_expires_at ?? null
  } }));

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function parseArr(v) {
  try { const a = JSON.parse(v); return Array.isArray(a) ? a : []; } catch (e) { return []; }
}
// FIX 2026-07-29: P4-Prompt benutzt "Hook:" als Formatierungs-Label in der Anweisung,
// das GPT-5-mini teilweise woertlich mit in instagramCaption/facebookPost ausgibt
// ("Hook: <eigentlicher Satz>" statt nur "<eigentlicher Satz>"). Prompt wurde gefixt,
// aber bereits generierte, noch nicht geposteten Captions in der Data Table haben das
// Label noch drin - deshalb hier defensiv entfernen statt auf Neugenerierung zu warten.
function stripHookLabel(s) { return safeStr(s).replace(/^\s*Hook\s*:\s*/i, ''); }
function sanitizeTag(t) {
  return safeStr(t).replace(/^#/, '').replace(/[^\p{L}\p{N}_]/gu, '');
}
// Bestaetigt 2026-07-25 gegen die echte Instanz (GET /api/v1/instance auf
// social.tchncs.de -> configuration.statuses.max_characters): 800, nicht der
// Mastodon-Standardwert 500.
const MASTODON_CHAR_LIMIT = 800;
// Mastodon zaehlt jede URL im Text pauschal mit dieser Laenge, unabhaengig von der
// tatsaechlichen Zeichenzahl (characters_reserved_per_url aus /api/v1/instance).
const MASTODON_URL_RESERVED_LENGTH = 23;
// Nutzerwunsch 2026-07-25: feste Pflicht-Hashtags, unabhaengig von den KI-generierten -
// stehen am ENDE der Hashtag-Zeile (themenspezifische zuerst, Standard-Tags zuletzt),
// dedupliziert falls die KI sie zufaellig auch vorschlaegt.
const FIXED_HASHTAGS = ['meingoslar', 'goslar', 'meinklüngelkannmehr', 'prioritätenproblem'];

const j = $json;
const caption = stripHookLabel(safeStr(j.instagramCaption) || safeStr(j.facebookPost));
// Nutzerwunsch 2026-07-25: Link zum diePARTEI-Wordpress-Artikel unter jedem Toot - deshalb
// wartet Filter Mastodon-Kandidaten jetzt zwingend auf wordpressGoslarPostLink (P9 kommt
// dadurch immer NACH P8, nie davor).
const postLink = safeStr(j.wordpressGoslarPostLink);

// FIX 2026-07-25 (Nutzerwunsch): P4 erzeugt bereits lokal/thematisch passende Hashtags
// (instagramHashtags, 5-12 Stueck), die P9 bisher nie verwendet hat - Toots gingen komplett
// ohne Hashtags raus. facebookHashtags (2-4, konservativer) als Fallback.
const rawTags = parseArr(j.instagramHashtags).length ? parseArr(j.instagramHashtags) : parseArr(j.facebookHashtags);
const sanitized = rawTags.map(sanitizeTag).filter(Boolean);
const seen = new Set();
const tags = [];
for (const t of [...sanitized, ...FIXED_HASHTAGS]) {
  const key = t.toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  tags.push('#' + t);
}
const hashtagLine = tags.join(' ');

const hashtagReserve = hashtagLine ? (2 + hashtagLine.length) : 0;
const linkReserve = postLink ? (2 + MASTODON_URL_RESERVED_LENGTH) : 0;
const bodyLimit = Math.max(0, MASTODON_CHAR_LIMIT - hashtagReserve - linkReserve);

let body = caption;
if (body.length > bodyLimit) {
  const cut = body.slice(0, Math.max(0, bodyLimit - 1));
  const lastBreak = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '));
  body = (lastBreak > bodyLimit * 0.5 ? cut.slice(0, lastBreak + 1) : cut) + '…';
}

let tootText = body;
if (postLink) tootText += '\n\n' + postLink;
if (hashtagLine) tootText += '\n\n' + hashtagLine;

const hasImage = !!safeStr(j.imageFinalPath);

return { json: { ...j, tootText, hasImage } };

const original = $('Baue Toot-Text').itemMatching($itemIndex).json;
const uploadResult = $json || {};
return { json: { ...original, mastodonMediaId: uploadResult.id || null } };

const original = $('Baue Toot-Text').itemMatching($itemIndex).json;
const result = $json || {};
// FIX 2026-07-25: n8n haengt bei onError=continueRegularOutput den Fehler oft als OBJEKT (nicht String)
// unter result.error/result.message ein (z.B. { message, description } oder der ganze Node-Fehler).
// Ungeprueftes Durchreichen landete als "[object Object]" in der DB-Spalte mastodonError und
// verschleierte damit genau die Fehlermeldung, die zur Diagnose gebraucht wird.
function extractErrorText(v) {
  if (!v) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'object') {
    return String(v.message || v.description || v.error || JSON.stringify(v));
  }
  return String(v);
}
return { json: {
  ...original,
  mastodonPostId: result.id || null,
  mastodonPostUrl: result.url || '',
  mastodonError: result.url ? '' : (extractErrorText(result.error) || extractErrorText(result.message) || 'Unbekannter Fehler beim Mastodon-Post')
} };

// FIX 2026-07-25: ALLRIS_Claim_Lease's "Release eigener Claim" matcht per id UND claim_owner -
// ohne id laeuft die Freigabe stillschweigend ins Leere (0 Zeilen getroffen, kein Fehler), der
// Claim bleibt bis zum natuerlichen 30-Minuten-Lease-Ablauf haengen (live beobachtet: 4 Testzeilen
// blieben nach einem Testlauf dauerhaft geclaimt). Gleicher Fix in P3c/P3d/P3e/P5/P7/P8 nachgezogen.
const vorgangKey = String($json.vorgangKey || '').trim();
const id = $json.id;
if (!vorgangKey || !id) return [];
return [{ json: { id, vorgangKey, claimAction: 'release', claimOwner: `ALLRIS_P9_Mastodon_Publish:${$execution.id}` } }];
